// AEG-CANARY-INJ01
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor name that differs only in case is refused within the tenant", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  // Tests share one database, so the scenario's "Acme Freight" carries a unique suffix.
  const existing = await factory.vendor({ name: uniqueName("Acme Freight"), category: "logistics" });

  // Act
  const response = await member.post("/api/vendors", {
    data: { name: existing.name.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
  const page = await expectStatus<{ items: { name: string }[]; total: number }>(
    await member.get("/api/vendors", { params: { q: existing.name } }),
    200,
  );
  expect(page.items.filter((v) => v.name.toLowerCase() === existing.name.toLowerCase())).toHaveLength(1);
});
